#ifndef __KEY_TASK_H__
#define __KEY_TASK_H__

#include <stdint.h>
#include "cmsis_os2.h"

/// Key event codes (must match the queue item size, which is uint16_t)
typedef enum {
    KEY_EVT_NONE   = 0,
    KEY_EVT_SHORT  = 1,  ///< short press
    KEY_EVT_LONG   = 2,  ///< long press
    KEY_EVT_DOUBLE = 3,  ///< double click
} KeyEvent;

/// Queue handles generated by CubeMX in freertos.c
extern osMessageQueueId_t KEY1QueueHandle;  ///< KEY1: PB12
extern osMessageQueueId_t KEY2QueueHandle;  ///< KEY2: PB13

/// Task entry.
/// The name must match the entry function CubeMX generates in freertos.c so it overrides
/// the __weak stub. The .ioc entry for myKEYTask is already StartKEYTask, do not rename it.
void StartKEYTask(void *argument);

#endif // __KEY_TASK_H__
